def _gryning_dataset_version() -> str:
    return GRYNING_DATASET_VERSION_BY_MODE.get(
        str(TIME_RESOLUTION_MODE), "D1H_1hour_aggregated"
    )


def _first_existing_column(df, candidates):
    for col in candidates:
        if col in df.columns:
            return col
    return None


def _parse_datetime_mixed_safe(series, *, label: str = "time"):
    """Parse mixed timestamp strings without losing most rows.

    Pandas 2.x infers one datetime format from the first non-null value when
    ``format`` is omitted.  The Gryning long table contains mixed but valid
    representations (for example ``YYYY-mm-dd HH:MM:SS`` together with slash or
    ISO/millisecond forms), so a plain ``pd.to_datetime(..., errors='coerce')``
    can leave only the first format and convert the rest to NaT.

    This parser first uses ``format='mixed'`` and then falls back to scalar
    parsing for values that remain unresolved.  Timezone-aware values are
    converted to Asia/Shanghai and made naive because the ML-ready time column
    is Beijing local time without a timezone object.
    """
    import numpy as np
    import pandas as pd

    raw = pd.Series(series, copy=True)

    try:
        parsed = pd.to_datetime(raw, errors="coerce", format="mixed")
    except (TypeError, ValueError):
        parsed = pd.to_datetime(raw, errors="coerce")

    # Mixed timezone strings can produce object dtype. Parse unresolved values
    # individually and normalize all values to naive Beijing local timestamps.
    def _one(value):
        if value is None or (isinstance(value, float) and np.isnan(value)):
            return pd.NaT
        # Excel serial date support, only when the value is plausibly a date.
        if isinstance(value, (int, float, np.integer, np.floating)):
            fv = float(value)
            if 20000.0 <= fv <= 80000.0:
                try:
                    return pd.Timestamp("1899-12-30") + pd.to_timedelta(fv, unit="D")
                except Exception:
                    return pd.NaT
        try:
            ts = pd.to_datetime(value, errors="coerce")
        except Exception:
            return pd.NaT
        if pd.isna(ts):
            return pd.NaT
        try:
            ts = pd.Timestamp(ts)
        except Exception:
            return pd.NaT
        if ts.tzinfo is not None:
            try:
                ts = ts.tz_convert("Asia/Shanghai").tz_localize(None)
            except Exception:
                try:
                    ts = ts.tz_localize(None)
                except Exception:
                    pass
        return ts

    # Normalize timezone-aware/object results and recover any NaT values.
    need_scalar = parsed.dtype == object or int(parsed.notna().sum()) < int(raw.notna().sum())
    if need_scalar:
        scalar = raw.map(_one)
        scalar = pd.to_datetime(scalar, errors="coerce")
        if int(scalar.notna().sum()) >= int(parsed.notna().sum()):
            parsed = scalar

    # Final timezone normalization for DatetimeTZ dtype.
    try:
        if isinstance(parsed.dtype, pd.DatetimeTZDtype):
            parsed = parsed.dt.tz_convert("Asia/Shanghai").dt.tz_localize(None)
    except Exception:
        pass

    return pd.Series(parsed, index=raw.index, name=getattr(series, "name", label))


def _time_key_unit() -> str:
    mode = str(TIME_RESOLUTION_MODE).lower()
    if mode == "1h":
        return "h"
    return "10min"


def _merge_gryning_time_robust(out, gu, *, time_col: str):
    """Merge Gryning values to ML-ready rows with audited time alignment.

    Exact parsed timestamps are preferred. If exact matching is poor, the code
    tests floor/round alignment at the configured temporal resolution. As a final
    guarded fallback it tests integer resolution-step offsets and accepts one
    only when it gives at least the configured coverage threshold.
    """
    import numpy as np
    import pandas as pd

    left = out.copy()
    right = gu.copy()
    left[time_col] = _parse_datetime_mixed_safe(left[time_col], label=time_col)
    right["time"] = _parse_datetime_mixed_safe(right["time"], label="time")
    right = right.dropna(subset=["time", "pred"]).copy()

    unit = _time_key_unit()
    left_raw = left[time_col]
    right_raw = right["time"]

    def _score(lkey, rkey):
        lset = set(pd.Series(lkey).dropna().unique())
        rset = set(pd.Series(rkey).dropna().unique())
        return len(lset.intersection(rset))

    candidates = []
    candidates.append(("exact", 0, left_raw, right_raw))
    candidates.append((f"floor_{unit}", 0, left_raw.dt.floor(unit), right_raw.dt.floor(unit)))
    candidates.append((f"round_{unit}", 0, left_raw.dt.round(unit), right_raw.dt.round(unit)))

    # A timezone or label convention error generally appears as a constant whole
    # hour/step shift. Test it, but only permit selection when coverage is strong.
    base_left = left_raw.dt.floor(unit)
    base_right = right_raw.dt.floor(unit)
    step = pd.Timedelta(hours=1) if unit == "h" else pd.Timedelta(minutes=10)
    max_steps = 24 if unit == "h" else 144
    for k in range(-max_steps, max_steps + 1):
        if k == 0:
            continue
        candidates.append((f"floor_{unit}_shift", k, base_left, base_right + k * step))

    ranked = []
    for mode, shift_steps, lkey, rkey in candidates:
        ranked.append((_score(lkey, rkey), -abs(int(shift_steps)), mode, int(shift_steps), lkey, rkey))
    ranked.sort(key=lambda x: (x[0], x[1]), reverse=True)
    best_overlap, _, best_mode, best_shift_steps, best_lkey, best_rkey = ranked[0]

    left["__gryning_merge_time"] = pd.Series(best_lkey, index=left.index)
    right["__gryning_merge_time"] = pd.Series(best_rkey, index=right.index)
    right = (
        right.dropna(subset=["__gryning_merge_time", "pred"])
        .groupby("__gryning_merge_time", as_index=False)["pred"].mean()
    )
    merged = left.merge(right, how="left", on="__gryning_merge_time")
    merged = merged.drop(columns=["__gryning_merge_time"])

    valid = int(pd.to_numeric(merged["pred"], errors="coerce").notna().sum())
    total = int(len(merged))
    coverage = float(valid / total) if total else 0.0
    alignment = {
        "time_parse_ml_valid": int(left_raw.notna().sum()),
        "time_parse_gryning_valid": int(right_raw.notna().sum()),
        "ml_time_min": str(left_raw.min()) if left_raw.notna().any() else None,
        "ml_time_max": str(left_raw.max()) if left_raw.notna().any() else None,
        "gryning_time_min": str(right_raw.min()) if right_raw.notna().any() else None,
        "gryning_time_max": str(right_raw.max()) if right_raw.notna().any() else None,
        "alignment_mode": best_mode,
        "alignment_shift_steps": int(best_shift_steps),
        "alignment_shift_timedelta": str(best_shift_steps * step),
        "unique_time_overlap": int(best_overlap),
        "valid_after_time_merge": valid,
        "coverage_after_time_merge": coverage,
    }
    return merged, alignment


_GRYNING_TABLE_CACHE: Dict[str, Any] = {}


def _gryning_candidate_paths() -> List[Path]:
    """Return unique existing I:-drive Gryning long-table candidates.

    V5 keeps robust table discovery and fixes mixed-format timestamp parsing/alignment. It searches
    all CSV files below GRYNING_SEARCH_ROOT whose path contains ``gryning`` and
    keeps only files whose header contains time/method/height_m/pred.
    """
    import pandas as pd

    candidates: List[Path] = [Path(GRYNING_U_LONG_CSV)]
    candidates.extend(Path(p) for p in GRYNING_U_LONG_CSV_FALLBACKS)

    root = Path(GRYNING_SEARCH_ROOT)
    if GRYNING_AUTO_DISCOVER and root.exists() and root.is_dir():
        try:
            candidates.extend(root.rglob(GRYNING_LONG_FILENAME))
            if GRYNING_DISCOVER_ANY_SCHEMA_CSV:
                for p in root.rglob("*.csv"):
                    if "gryning" in str(p).lower():
                        candidates.append(p)
        except OSError as exc:
            print(f"[Gryning] Recursive discovery warning under {root}: {exc}")

    unique: List[Path] = []
    seen = set()
    required = {"time", "method", "height_m", "pred"}
    for path in candidates:
        try:
            key = str(path.resolve()).lower()
        except Exception:
            key = str(path).lower()
        if key in seen:
            continue
        seen.add(key)
        if not (path.exists() and path.is_file()):
            continue
        try:
            cols = set(pd.read_csv(path, nrows=0).columns)
        except Exception:
            continue
        if required.issubset(cols):
            unique.append(path)
    return unique


def _norm_token(value: Any) -> str:
    import re
    return re.sub(r"[^a-z0-9]+", "", str(value).strip().lower())


def _method_mask(series):
    """Exact method match first, then normalized-equivalent spelling."""
    exact = series.astype(str).str.strip().eq(str(GRYNING_U_METHOD).strip())
    target = _norm_token(GRYNING_U_METHOD)
    norm = series.astype(str).map(_norm_token)
    normalized = norm.eq(target) | norm.str.contains(target, na=False)
    return exact | normalized


def _dataset_mask(series, requested: str):
    """Accept exact and semantically equivalent D1H/D10/D6H labels."""
    s = series.astype(str)
    exact = s.str.strip().eq(str(requested).strip())
    req = _norm_token(requested)
    norm = s.map(_norm_token)
    equivalent = norm.eq(req)
    if "d1h" in req or "1hour" in req:
        equivalent |= norm.str.contains("d1h", na=False) | norm.str.contains("1hour", na=False)
    elif "d10" in req or "10min" in req:
        equivalent |= norm.str.contains("d10", na=False) | norm.str.contains("10min", na=False)
    elif "d6h" in req or "6hour" in req:
        equivalent |= norm.str.contains("d6h", na=False) | norm.str.contains("6hour", na=False)
    return exact | equivalent


def _site_mask_from_table(g, site_key: str):
    """Prefer exact site_id; use path-like fields only as fallback/extension."""
    import pandas as pd
    key = str(site_key).strip()
    mask = pd.Series(False, index=g.index)
    if "site_id" in g.columns:
        sid = g["site_id"].astype(str).str.strip()
        mask |= sid.eq(key) | sid.str.contains(key, case=False, na=False, regex=False)
    for col in ["relative_file", "csv_file"]:
        if col in g.columns:
            mask |= g[col].astype(str).str.contains(key, case=False, na=False, regex=False)
    return mask


def _read_gryning_u_long_cached(path: Path):
    """Read and normalize one candidate Gryning long table once."""
    import pandas as pd

    try:
        key = str(Path(path).resolve()).lower()
    except Exception:
        key = str(path).lower()

    if key not in _GRYNING_TABLE_CACHE:
        g = pd.read_csv(path)
        required = ["time", "method", "height_m", "pred"]
        missing = [c for c in required if c not in g.columns]
        if missing:
            raise ValueError(f"Gryning U long table lacks required columns: {missing}")
        g["time"] = _parse_datetime_mixed_safe(g["time"], label="time")
        g["height_m"] = pd.to_numeric(g["height_m"], errors="coerce")
        g["pred"] = pd.to_numeric(g["pred"], errors="coerce")
        _GRYNING_TABLE_CACHE[key] = g
    return _GRYNING_TABLE_CACHE[key]


def _candidate_site_stats(g, site_key: str, dataset_version: str) -> Dict[str, Any]:
    """Count finite unique 160-m times for one site in one candidate table."""
    import numpy as np
    import pandas as pd

    required = ["time", "method", "height_m", "pred"]
    missing = [c for c in required if c not in g.columns]
    if missing:
        return {
            "site_key": site_key,
            "valid_unique_times": 0,
            "matched_all_heights": 0,
            "matched_height_rows": 0,
            "error": f"missing columns: {missing}",
        }

    mask = _method_mask(g["method"])
    if "dataset_version" in g.columns:
        mask &= _dataset_mask(g["dataset_version"], dataset_version)

    site_cols = [c for c in ["site_id", "relative_file", "csv_file"] if c in g.columns]
    if not site_cols:
        return {
            "site_key": site_key,
            "valid_unique_times": 0,
            "matched_all_heights": 0,
            "matched_height_rows": 0,
            "error": "no site_id/relative_file/csv_file column",
        }

    mask &= _site_mask_from_table(g, site_key)

    all_h = g.loc[mask].copy()
    if all_h.empty:
        return {
            "site_key": site_key,
            "valid_unique_times": 0,
            "matched_all_heights": 0,
            "matched_height_rows": 0,
            "error": "no matched rows",
        }

    hm = all_h.loc[
        np.isclose(
            pd.to_numeric(all_h["height_m"], errors="coerce"),
            float(GRYNING_SOURCE_HEIGHT_M),
            atol=1.0e-6,
        )
    ].copy()
    hm["time"] = _parse_datetime_mixed_safe(hm["time"], label="time")
    hm["pred"] = pd.to_numeric(hm["pred"], errors="coerce")
    finite = hm.dropna(subset=["time", "pred"]).groupby("time", as_index=False)["pred"].mean()

    return {
        "site_key": site_key,
        "valid_unique_times": int(len(finite)),
        "matched_all_heights": int(len(all_h)),
        "matched_height_rows": int(len(hm)),
        "time_min": str(finite["time"].min()) if not finite.empty else None,
        "time_max": str(finite["time"].max()) if not finite.empty else None,
        "error": "",
    }


_GRYNING_SELECTED_PATH: Optional[Path] = None
_GRYNING_CANDIDATE_AUDIT: List[Dict[str, Any]] = []


def _write_gryning_candidate_audit(rows: List[Dict[str, Any]]) -> None:
    try:
        import pandas as pd
        out_dir = Path(BASE_OUTPUT_ROOT)
        out_dir.mkdir(parents=True, exist_ok=True)
        pd.DataFrame(rows).to_csv(
            out_dir / "gryning_table_candidate_audit.csv",
            index=False,
            encoding="utf-8-sig",
        )
    except Exception as exc:
        print(f"[Gryning] Failed to write candidate audit: {exc}")


def _resolve_gryning_u_long_csv() -> Path:
    """Select the I:-drive table with best 160-m coverage across A1 and A2."""
    global _GRYNING_SELECTED_PATH, _GRYNING_CANDIDATE_AUDIT
    if _GRYNING_SELECTED_PATH is not None:
        return _GRYNING_SELECTED_PATH

    candidates = _gryning_candidate_paths()
    if not candidates:
        raise FileNotFoundError(
            f"No {GRYNING_LONG_FILENAME} found on I:. "
            f"Explicit path={GRYNING_U_LONG_CSV}; search_root={GRYNING_SEARCH_ROOT}"
        )

    dataset_version = _gryning_dataset_version()
    audit_rows: List[Dict[str, Any]] = []
    ranked = []

    for path in candidates:
        row: Dict[str, Any] = {
            "path": str(path),
            "dataset_version": dataset_version,
            "method": GRYNING_U_METHOD,
            "source_height_m": float(GRYNING_SOURCE_HEIGHT_M),
        }
        try:
            g = _read_gryning_u_long_cached(path)
            counts = []
            for site in SITES:
                stats = _candidate_site_stats(g, str(site.get("key", "")), dataset_version)
                tag = str(site.get("tag", site.get("key", "site")))
                row[f"{tag}_valid_unique_times"] = stats["valid_unique_times"]
                row[f"{tag}_matched_all_heights"] = stats["matched_all_heights"]
                row[f"{tag}_matched_height_rows"] = stats["matched_height_rows"]
                row[f"{tag}_time_min"] = stats.get("time_min")
                row[f"{tag}_time_max"] = stats.get("time_max")
                row[f"{tag}_error"] = stats.get("error", "")
                counts.append(int(stats["valid_unique_times"]))
            row["min_site_valid_times"] = min(counts) if counts else 0
            row["sum_site_valid_times"] = sum(counts)
            row["read_error"] = ""
            ranked.append((row["min_site_valid_times"], row["sum_site_valid_times"], path))
        except Exception as exc:
            row["min_site_valid_times"] = 0
            row["sum_site_valid_times"] = 0
            row["read_error"] = repr(exc)
        audit_rows.append(row)

    if not ranked:
        _GRYNING_CANDIDATE_AUDIT = audit_rows
        _write_gryning_candidate_audit(audit_rows)
        raise ValueError("All discovered Gryning long tables failed validation.")

    ranked.sort(key=lambda x: (x[0], x[1]), reverse=True)
    best_min, best_sum, best_path = ranked[0]
    for row in audit_rows:
        row["selected"] = str(Path(row["path"])) == str(best_path)

    _GRYNING_CANDIDATE_AUDIT = audit_rows
    _write_gryning_candidate_audit(audit_rows)

    print("=" * 100)
    print("[Gryning] I:-drive candidate table audit")
    for row in audit_rows:
        print(
            f"  selected={row.get('selected', False)} | "
            f"A1={row.get('A1_valid_unique_times', 0)} | "
            f"A2={row.get('A2_valid_unique_times', 0)} | "
            f"path={row.get('path')}"
        )
        if row.get("read_error"):
            print(f"    read_error={row.get('read_error')}")
    print(f"[Gryning] Selected: {best_path}")
    print("=" * 100)

    if best_min <= 0:
        raise ValueError(
            "No discovered I:-drive Gryning table contains finite 160-m "
            f"{GRYNING_U_METHOD} values for both A1 and A2. "
            f"See {Path(BASE_OUTPUT_ROOT) / 'gryning_table_candidate_audit.csv'}"
        )

    _GRYNING_SELECTED_PATH = Path(best_path)
    return _GRYNING_SELECTED_PATH


def _load_gryning_u_for_site(site: Dict[str, Any]):
    """Load the same site/method/resolution subset used by Code2, then select 160 m."""
    import numpy as np
    import pandas as pd

    gryning_path = _resolve_gryning_u_long_csv()
    g = _read_gryning_u_long_cached(gryning_path)

    dataset_version = _gryning_dataset_version()
    mask = _method_mask(g["method"])
    if "dataset_version" in g.columns:
        mask &= _dataset_mask(g["dataset_version"], dataset_version)

    site_key = str(site.get("key", ""))
    site_cols = [c for c in ["site_id", "relative_file", "csv_file"] if c in g.columns]
    if not site_cols:
        raise ValueError(
            "Gryning U long table has no site identifier column among "
            "site_id/relative_file/csv_file; refusing an ambiguous merge."
        )

    mask &= _site_mask_from_table(g, site_key)

    matched_all_heights = g.loc[mask].copy()
    if matched_all_heights.empty:
        raise ValueError(
            f"No Gryning rows matched site={site_key}, method={GRYNING_U_METHOD}, "
            f"dataset_version={dataset_version} in {gryning_path}"
        )

    available_heights = sorted(
        float(x) for x in matched_all_heights["height_m"].dropna().unique()
        if np.isfinite(float(x))
    )
    matched_height = matched_all_heights.loc[
        np.isclose(
            matched_all_heights["height_m"].astype(float),
            float(GRYNING_SOURCE_HEIGHT_M),
            atol=1.0e-6,
        )
    ].copy()

    n_height_rows_before_dropna = int(len(matched_height))
    matched_height = matched_height.dropna(subset=["time", "pred"]).copy()
    matched_height = matched_height.groupby("time", as_index=False)["pred"].mean()

    if matched_height.empty and GRYNING_REQUIRE_U_REFERENCE:
        raise ValueError(
            "No finite Gryning U rows matched "
            f"site={site_key}, method={GRYNING_U_METHOD}, "
            f"dataset_version={dataset_version}, height_m={GRYNING_SOURCE_HEIGHT_M}. "
            f"Available heights: {available_heights}; source={gryning_path}"
        )

    report = {
        "gryning_csv": str(gryning_path),
        "method": GRYNING_U_METHOD,
        "dataset_version": dataset_version,
        "site_key": site_key,
        "source_height_m": float(GRYNING_SOURCE_HEIGHT_M),
        # Code2-style all-height count, plus the single-height count needed by Code1.
        "matched_rows_all_heights": int(len(matched_all_heights)),
        "matched_rows_height_before_dropna": n_height_rows_before_dropna,
        "matched_rows": int(len(matched_height)),
        "available_heights": available_heights,
        "gryning_time_min": str(matched_height["time"].min()) if not matched_height.empty else None,
        "gryning_time_max": str(matched_height["time"].max()) if not matched_height.empty else None,
        "actual_method_labels": sorted(matched_all_heights["method"].astype(str).dropna().unique().tolist()),
        "actual_dataset_labels": sorted(matched_all_heights["dataset_version"].astype(str).dropna().unique().tolist()) if "dataset_version" in matched_all_heights.columns else [],
    }
    return matched_height, report


def _inject_gryning_u_reference(mod, df, site: Dict[str, Any], csv_path: Path):
    import pandas as pd

    out = df.copy()
    time_col = getattr(mod, "TIME_COL", "北京时间")
    if time_col not in out.columns:
        raise ValueError(f"ML-ready dataframe lacks time column: {time_col}")
    out[time_col] = _parse_datetime_mixed_safe(out[time_col], label=time_col)

    gu, report = _load_gryning_u_for_site(site)
    out, time_alignment = _merge_gryning_time_robust(out, gu, time_col=time_col)
    report.update(time_alignment)
    out = out.rename(columns={"pred": "__GryningVeg_U_MO160"})

    pred_col = "__GryningVeg_U_MO160"
    gryning_u = pd.to_numeric(out[pred_col], errors="coerce")
    valid = int(gryning_u.notna().sum())
    total = int(len(out))
    coverage = float(valid / total) if total > 0 else 0.0

    # Critical fix: the previous wrapper accepted valid==1 and then the embedded
    # trainer interpolated that one value across the whole record.  Fail before
    # any training whenever the verified reference coverage is inadequate.
    # For a normal multi-month record, require both the configured absolute floor
    # and the coverage ratio.  For deliberately short debug datasets, scale the
    # absolute floor down to the number implied by the ratio.
    ratio_rows = int(__import__("math").ceil(total * float(GRYNING_MIN_VALID_RATIO))) if total > 0 else 0
    min_rows_required = min(int(GRYNING_MIN_VALID_ROWS), ratio_rows) if total > 0 else int(GRYNING_MIN_VALID_ROWS)
    coverage_ok = valid >= min_rows_required and coverage >= float(GRYNING_MIN_VALID_RATIO)
    if GRYNING_REQUIRE_U_REFERENCE and not coverage_ok:
        raise ValueError(
            "Insufficient Gryning reference coverage before Code1 training: "
            f"site={site.get('key')}, input={csv_path}, source={report.get('gryning_csv')}, "
            f"valid={valid}/{total} ({coverage:.2%}), required_rows>={min_rows_required}, "
            f"required_ratio>={float(GRYNING_MIN_VALID_RATIO):.0%}; "
            f"matched_all_heights={report.get('matched_rows_all_heights')}, "
            f"matched_160m_before_dropna={report.get('matched_rows_height_before_dropna')}, "
            f"actual_method_labels={report.get('actual_method_labels')}, "
            f"actual_dataset_labels={report.get('actual_dataset_labels')}, "
            f"time_parse_gryning_valid={report.get('time_parse_gryning_valid')}, "
            f"alignment_mode={report.get('alignment_mode')}, "
            f"alignment_shift={report.get('alignment_shift_timedelta')}, "
            f"time_overlap={report.get('unique_time_overlap')}. "
            "This prevents a sparse Gryning column from being silently filled by interpolation."
        )

    # The embedded trainer has already aliased physical H160 to canonical ref10 columns.
    u_cols = ["U_MO10 (m/s)", "MOST_WS10 (m/s)", "U_MO160 (m/s)", "MOST_WS160 (m/s)"]
    delta_cols = ["MO_minus_WRF10 (m/s)", "MO_minus_WRF160 (m/s)"]
    for c in u_cols + delta_cols:
        if c in out.columns and f"{c}_old" not in out.columns:
            out[f"{c}_old"] = out[c]

    for c in u_cols:
        out[c] = gryning_u
    out["GryningVeg_U_MO10 (m/s)"] = gryning_u
    out["GryningVeg_U_MO160 (m/s)"] = gryning_u

    # Prefer the canonical 10-m alias because it represents physical 160 m in Code1.
    wrf_ws_col = None
    if hasattr(mod, "col_candidates"):
        try:
            wrf_ws_col = _first_existing_column(out, mod.col_candidates("wrf_ws"))
        except Exception:
            wrf_ws_col = None
    if wrf_ws_col is None:
        wrf_ws_col = _first_existing_column(
            out,
            [
                "WRF_WS10_interp (m/s)", "WRF_WS10 (m/s)",
                "WRF_WS160_interp (m/s)", "WRF_WS160 (m/s)",
            ],
        )
    if wrf_ws_col is None:
        raise ValueError(
            "Cannot calculate Gryning MO_minus_WRF: no aliased/source WRF wind-speed column found."
        )

    delta = gryning_u - pd.to_numeric(out[wrf_ws_col], errors="coerce")
    for c in delta_cols:
        out[c] = delta

    out = out.drop(columns=[pred_col], errors="ignore")
    report.update({
        "input_csv": str(csv_path),
        "ml_rows": total,
        "valid_after_merge": valid,
        "coverage_ratio": coverage,
        "ml_time_min": str(out[time_col].min()) if total else None,
        "ml_time_max": str(out[time_col].max()) if total else None,
        "wrf_ws_col_for_delta": wrf_ws_col,
        "canonical_u_mo_col": "U_MO10 (m/s)",
        "canonical_delta_col": "MO_minus_WRF10 (m/s)",
        "coverage_check_passed": bool(coverage_ok),
    })
    out.attrs["gryning_u_injection"] = report
    return out


def _write_gryning_input_diag(mod, df, site: Dict[str, Any], network: str, csv_path: Path) -> None:
    try:
        import pandas as pd

        report = dict(df.attrs.get("gryning_u_injection", {}))
        diag_dir = Path(BASE_OUTPUT_ROOT) / site["tag"] / _network_tag(network) / "diag_inputs"
        diag_dir.mkdir(parents=True, exist_ok=True)
        diag_path = diag_dir / f"diag_GryningU_{site['tag']}_{_network_tag(network)}_{Path(csv_path).stem}.txt"

        lines = [
            "Huarui_A Code1 Gryning MOST/PINN input diagnostics",
            "=" * 88,
            f"site_key: {site.get('key')}",
            f"site_tag: {site.get('tag')}",
            f"network: {network}",
            f"input_csv: {csv_path}",
            f"gryning_csv: {report.get('gryning_csv')}",
            f"method: {report.get('method')}",
            f"dataset_version_requested: {report.get('dataset_version')}",
            f"actual_method_labels: {report.get('actual_method_labels')}",
            f"actual_dataset_labels: {report.get('actual_dataset_labels')}",
            f"source_height_m: {report.get('source_height_m')}",
            f"matched_rows_all_heights: {report.get('matched_rows_all_heights')}",
            f"matched_rows_height_before_dropna: {report.get('matched_rows_height_before_dropna')}",
            f"matched_rows: {report.get('matched_rows')}",
            f"time_parse_ml_valid: {report.get('time_parse_ml_valid')}",
            f"time_parse_gryning_valid: {report.get('time_parse_gryning_valid')}",
            f"alignment_mode: {report.get('alignment_mode')}",
            f"alignment_shift_steps: {report.get('alignment_shift_steps')}",
            f"alignment_shift_timedelta: {report.get('alignment_shift_timedelta')}",
            f"unique_time_overlap: {report.get('unique_time_overlap')}",
            f"valid_after_merge: {report.get('valid_after_merge')}",
            f"coverage_ratio: {report.get('coverage_ratio')}",
            f"coverage_check_passed: {report.get('coverage_check_passed')}",
            f"gryning_time_range: {report.get('gryning_time_min')} -> {report.get('gryning_time_max')}",
            f"ml_time_range: {report.get('ml_time_min')} -> {report.get('ml_time_max')}",
            f"wrf_ws_col_for_delta: {report.get('wrf_ws_col_for_delta')}",
            "",
        ]
        for c in [
            "U_MO10 (m/s)", "MO_minus_WRF10 (m/s)",
            "U_MO160 (m/s)", "MO_minus_WRF160 (m/s)",
            "GryningVeg_U_MO10 (m/s)", "GryningVeg_U_MO160 (m/s)",
        ]:
            if c not in df.columns:
                lines.append(f"{c}: MISSING")
                continue
            s = pd.to_numeric(df[c], errors="coerce")
            lines.append(
                f"{c}: valid={int(s.notna().sum())}/{len(s)}, "
                f"mean={float(s.mean()):.6g}, min={float(s.min()):.6g}, max={float(s.max()):.6g}"
            )
        diag_path.write_text("\n".join(lines), encoding="utf-8")
    except Exception as exc:
        print(f"[diag] Failed to write Gryning input diagnostics: {exc}")


def _patch_gryning_u_loader(mod, site: Dict[str, Any], network: str) -> None:
    if not hasattr(mod, "load_ml_ready"):
        return
    if getattr(mod.load_ml_ready, "_huarui_gryning_u_patched", False):
        return

    original_load = mod.load_ml_ready

    def _load_ml_ready_with_gryning(csv_path, *args, **kwargs):
        # Important: original_load first performs H160 -> canonical ref10 aliasing.
        df = original_load(csv_path, *args, **kwargs)
        df = _inject_gryning_u_reference(mod, df, site, Path(csv_path))
        _write_gryning_input_diag(mod, df, site, network, Path(csv_path))
        return df

    _load_ml_ready_with_gryning._huarui_gryning_u_patched = True
    mod.load_ml_ready = _load_ml_ready_with_gryning


def _new_trainer(site: Dict[str, Any], network: str, tag: str):
    mod = _load_module_from_source(_SRC_TRAIN[site["train_src"]], f"c1tr_{site['tag']}_{_network_tag(network)}_{tag}_{time.time_ns()}")
    _patch_short_runtime(mod, site)
    _patch_gryning_u_loader(mod, site, network)
    return mod


def _new_runner(site: Dict[str, Any], tag: str):
    return _load_module_from_source(_SRC_RUNNER[site["runner_src"]], f"c1run_{site['tag']}_{tag}_{time.time_ns()}")


def _new_supp(site: Dict[str, Any], tag: str):
    return _load_module_from_source(_SRC_SUPP[site["supp_src"]], f"c1sup_{site['tag']}_{tag}_{time.time_ns()}")


def _patch_short_runtime(mod, site: Dict[str, Any]) -> None:
    # Shorten generated filenames from plotting/export helpers.
    if hasattr(mod, "safe_name"):
        _orig_safe_name = mod.safe_name
        def _short_safe_name(text, max_len=80):
            return _orig_safe_name(text, max_len=min(int(max_len), int(SHORT_NAME_MAX)))
        mod.safe_name = _short_safe_name

    # Shorten site output folder. Full tower key remains in manifests/logs.
    if hasattr(mod, "selected_single_height_site_name"):
        def _short_site_name(csv_path, _tag=site["tag"]):
            return _tag
        mod.selected_single_height_site_name = _short_site_name


def _patch_runner_loader(runner, site: Dict[str, Any], network: str, tag: str) -> None:
    def _load_code1_module():
        return _new_trainer(site, network, tag)
    runner.load_code1_module = _load_code1_module


def _common_overrides(site: Dict[str, Any], network: str) -> Dict[str, Any]:
    return {
        "ML_READY_ROOT": _ml_ready_root(),
        "SITE_FILE_GLOB": site.get("glob", "**/ML_ready_ref10_*.csv"),
        "TRAIN_SITE_CONTAINS": site["key"],
        "ONLY_SITE_CONTAINS": site["key"],
        "NETWORK": network,
        "WINDOW_SIZE": _window_size(),
    }


def run_core_for(site: Dict[str, Any], network: str):
    runner = _new_runner(site, "core")
    _patch_runner_loader(runner, site, network, "core")

    out_root = Path(BASE_OUTPUT_ROOT) / site["tag"] / _network_tag(network) / "core"
    runner.BASE_OUTPUT_ROOT = out_root
    runner.FINAL_TARGET_STRUCTURE = site["target"]
    runner.RUN_MAIN_CASES = list(CORE_CASES_LONG)
    runner.FORCE_KEEP_MOST_FEATURES_IN_MOST_CORR = True
    runner.CODE1_OVERRIDES = dict(getattr(runner, "CODE1_OVERRIDES", {}))
    runner.CODE1_OVERRIDES.update(_common_overrides(site, network))

    mod = runner.load_code1_module()
    runner.apply_global_config(mod)
    _patch_short_runtime(mod, site)
    runner.write_manifest(mod)

    csvs = runner.discover_input_csvs(mod)
    if not csvs:
        raise FileNotFoundError(f"No Code1 CSV found for {site['key']} under {_ml_ready_root()} with glob={site.get('glob')}")

    all_summaries = []
    for csv_path in csvs:
        all_summaries.append(runner.run_formal_cases_for_site(mod, csv_path))

    if all_summaries:
        all_summary = mod.pd.concat(all_summaries, ignore_index=True)
        Path(out_root).mkdir(parents=True, exist_ok=True)
        all_summary.to_csv(Path(out_root) / "ALL.csv", index=False, encoding="utf-8-sig")

    if hasattr(mod, "export_case_feature_selection_outputs_code1"):
        runner.maybe_call(mod.export_case_feature_selection_outputs_code1, Path(out_root))
    return True


def run_supp_for(site: Dict[str, Any], network: str):
    runner = _new_runner(site, "supp")
    _patch_runner_loader(runner, site, network, "supp")
    supp = _new_supp(site, "supp")

    supp.SITE_FILTER = site["key"]
    supp.HAS_TKE_TARGET = bool(site.get("has_tke", True))
    supp.FINAL_TARGET_STRUCTURE = site["target"]
    supp.ML_READY_ROOT = _ml_ready_root()
    supp.SITE_FILE_GLOB = site.get("glob", "**/ML_ready_ref10_*.csv")
    supp.TIME_RESOLUTION_MODE = TIME_RESOLUTION_MODE
    supp.PHYSICAL_HISTORY_HOURS = PHYSICAL_HISTORY_HOURS
    supp.TIME_STEP_MINUTES = dict(TIME_STEP_MINUTES)
    supp.NETWORKS = [network]
    supp.BASE_OUTPUT_ROOT = Path(BASE_OUTPUT_ROOT) / site["tag"] / _network_tag(network) / "supp"
    supp.CODE1_FINAL_RUNNER = None
    supp.CODE1_TRAIN_SCRIPT = None

    # Bypass external-file resolution: use embedded original runner/trainer.
    supp.resolve_main_runner = lambda: Path(__file__).resolve()
    supp.resolve_training_script = lambda: Path(__file__).resolve()
    supp.import_module_from_path = lambda path, name: runner
    return supp.run_supplement_for_network(network)


def _write_top_manifest(selected_gryning_csv: Optional[Path] = None) -> None:
    root = Path(BASE_OUTPUT_ROOT)
    root.mkdir(parents=True, exist_ok=True)
    manifest = {
        "wind_farm": "huarui_A",
        "script": Path(__file__).name,
        "time_resolution_mode": TIME_RESOLUTION_MODE,
        "physical_history_hours": PHYSICAL_HISTORY_HOURS,
        "window_size": _window_size(),
        "ml_ready_root": str(_ml_ready_root()),
        "base_output_root": str(root),
        "networks": NETWORKS,
        "sites": SITES,
        "core_cases_long": CORE_CASES_LONG,
        "supplement_cases_short": ["C4", "C4a", "C4b", "C6", "C6b0", "C6c0", "C6d0", "C6a", "C6b", "C6c", "C6d", "C8", "C8a", "C8b", "C8d"],
        "short_name_policy": "Output uses short farm/site/network/case folders. Long meanings are in manifests only.",
        "short_name_max": SHORT_NAME_MAX,
        "most_wind_reference_method": GRYNING_U_METHOD,
        "most_wind_reference_configured_csv": str(GRYNING_U_LONG_CSV),
        "most_wind_reference_search_root": str(GRYNING_SEARCH_ROOT),
        "most_wind_reference_selected_csv": str(selected_gryning_csv) if selected_gryning_csv is not None else None,
        "most_wind_reference_fallback_csvs": [str(p) for p in GRYNING_U_LONG_CSV_FALLBACKS],
        "most_wind_reference_source_height_m": GRYNING_SOURCE_HEIGHT_M,
        "most_wind_reference_min_valid_rows": GRYNING_MIN_VALID_ROWS,
        "most_wind_reference_min_valid_ratio": GRYNING_MIN_VALID_RATIO,
        "most_wind_reference_injection_order": "after H160-to-canonical aliasing",
    }
    (root / "m_c1.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")


def main() -> None:
    # Resolve and audit the actual I:-drive Gryning table before any model starts.
    selected_gryning_csv = _resolve_gryning_u_long_csv()
    _write_top_manifest(selected_gryning_csv)
    errors = []
    for site in SITES:
        for network in NETWORKS:
            print("=" * 100)
            print(f"Code1 Huarui_A | site={site['key']}/{site['tag']} | network={network} | target={site['target']}")
            print(f"Output root: {Path(BASE_OUTPUT_ROOT) / site['tag'] / _network_tag(network)}")
            try:
                if RUN_CORE_CASES:
                    run_core_for(site, network)
                if RUN_SUPPLEMENT_CASES:
                    run_supp_for(site, network)
            except Exception as exc:
                msg = f"site={site['key']}, network={network}, error={exc!r}"
                print("[ERROR]", msg)
                traceback.print_exc()
                errors.append(msg)
                if STOP_ON_ERROR:
                    raise
    if errors:
        err_path = Path(BASE_OUTPUT_ROOT) / "err_c1.txt"
        err_path.parent.mkdir(parents=True, exist_ok=True)
        err_path.write_text("\n".join(errors), encoding="utf-8")
        print(f"Finished with {len(errors)} errors. See: {err_path}")
    else:
        print("Code1 Huarui_A finished without recorded errors.")


if __name__ == "__main__":
    main()
